const OMGS_SEARCH = [{"page": "Home", "head": "", "url": "index.html", "text": "Riverton & Herriman, Utah · Centennial Park · Western Springs · Tuscany East Learn the Game. Play It. Love It. Recreational girls softball for 500+ girls ages 3 to 18 each season. We teach the fundamentals in a safe, fun setting and help girls build skills, sportsmanship, and confidence. Register Find my division Registration is on Sports Connect. You will sign in or create an account first. Building Skills Building Character Building Champions Building Skills Building Character Building Champions Building Skills Building Character Building Champions Building Skills Building Character Building Champions What's next"}, {"page": "Home", "head": "Four waysto get in the game.", "url": "index.html", "text": "Four ways to get in the game. 01"}, {"page": "Home", "head": "Register", "url": "index.html", "text": "Register Spring registration usually opens in mid-January. The 2027 date is not set yet. Every Register button goes straight to sign-up. Register now 02"}, {"page": "Home", "head": "Schedule", "url": "index.html", "text": "Schedule Season dates, drafts, meetings, and All-Star events. Game schedules are coming soon. View dates 03"}, {"page": "Home", "head": "Standings", "url": "index.html", "text": "Standings Tournament seeding is by league win/loss record. Standings are coming soon. Tournament rules 04"}, {"page": "Home", "head": "All-Stars", "url": "index.html", "text": "All-Stars Summer All-Star teams for 8U through 18U, with the OMGS Invitational and D1 State Tournament. 2027 dates are coming soon. All-Star info Our values"}, {"page": "Home", "head": "Play like a GIRL.", "url": "index.html", "text": "Play like a GIRL. G Grit I Integrity R Respect L Love for the Game The OMGS standard"}, {"page": "Home", "head": "Building Skills.Building Character.Building Champions.", "url": "index.html", "text": "Building Skills. Building Character. Building Champions. 01 · SKILLS"}, {"page": "Home", "head": "Taught right, from the ground up.", "url": "index.html", "text": "Taught right, from the ground up. Fundamentals in a safe and enjoyable setting, with a free coaches clinic and free preseason pitching clinics. 02 · CHARACTER"}, {"page": "Home", "head": "Teammates first. Always.", "url": "index.html", "text": "Teammates first. Always. Good sportsmanship, positive cheers, and zero tolerance for abusive behavior from anyone at the park. 03 · COMMUNITY"}, {"page": "Home", "head": "A whole park behind every girl.", "url": "index.html", "text": "A whole park behind every girl. Players from 20+ cities across Salt Lake and Utah County, plus volunteer coaches, team parents, Snack Shack crews, and clean-up days. Fun, growth, and friendships that last all season. Three seasons"}, {"page": "Home", "head": "Spring. Summer. Fall.", "url": "index.html", "text": "Spring. Summer. Fall. Spring"}, {"page": "Home", "head": "Spring season", "url": "index.html", "text": "Spring season Our main league season. Registration usually opens in mid-January. Players attend a skill assessment (tryout) before draft day, then teams are drafted. Coach picks do not need to attend. Summer"}, {"page": "Home", "head": "All-Stars", "url": "index.html", "text": "All-Stars June 1 to early August, for selected 8U to 18U players. All-Stars have their own tryout and draft, separate from spring. Fall"}, {"page": "Home", "head": "Fall season", "url": "index.html", "text": "Fall season Mid-August to October. There is no draft in the fall. OMGS puts the teams together. See important dates &rarr; Game day ops"}, {"page": "Home", "head": "Field status.Important dates.", "url": "index.html", "text": "Field status. Important dates. Field status"}, {"page": "Home", "head": "OMGS fields", "url": "index.html", "text": "OMGS fields Fields & directions Important dates"}, {"page": "Home", "head": "Mark your calendar.", "url": "index.html", "text": "Mark your calendar. Full calendar Get involved"}, {"page": "Home", "head": "It takes a whole park.", "url": "index.html", "text": "It takes a whole park."}, {"page": "Home", "head": "Coach", "url": "index.html", "text": "Coach Lead a team. Online application, background check, and Child Safety Training required. Applications open soon."}, {"page": "Home", "head": "Snack Shack crew", "url": "index.html", "text": "Snack Shack crew Each team provides one volunteer (14 or older) for its scheduled shifts."}, {"page": "Home", "head": "Umpires", "url": "index.html", "text": "Umpires D1 Prospects handles umpires for 10U and up. Brooke Olsen, our Vice President, handles 8U umpires: brooke@omgsoftball.org ."}, {"page": "Home", "head": "Join the Board", "url": "index.html", "text": "Join the Board We are looking for new board members for Spring. Open seats are posted, and applicants are interviewed by the Board. Join the board"}, {"page": "Home", "head": "We're looking for new board members for Spring.", "url": "index.html", "text": "We're looking for new board members for Spring. Help run the league your daughter plays in. Email us to apply. The Board interviews applicants and fills open seats by vote. Email contact@omgsoftball.org News"}, {"page": "Home", "head": "Latest from OMGS", "url": "index.html", "text": "Latest from OMGS Quick find"}, {"page": "Home", "head": "Search the site", "url": "index.html", "text": "Search the site Search Searches rules, FAQ, dates, fields, and more. Proud partners of OMGS Become a sponsor Follow OMGS"}, {"page": "Home", "head": "Stay in the loop.", "url": "index.html", "text": "Stay in the loop. Game day news, photos, and reminders. Facebook Instagram"}, {"page": "Home", "head": "Ready to play?", "url": "index.html", "text": "Ready to play? Spring registration usually opens in mid-January. Register"}, {"page": "About & Board", "head": "Our mission", "url": "about.html", "text": "Our mission To provide a quality recreational softball program by teaching the fundamentals of softball in a safe and enjoyable atmosphere. To provide opportunities to improve softball skills and learn the value of good sportsmanship while enhancing self-esteem."}, {"page": "About & Board", "head": "Our seasons", "url": "about.html", "text": "Our seasons OMGS runs three seasons each year: the Spring season, All-Stars in the summer (June 1 to early August), and the Fall season (mid-August to October)."}, {"page": "About & Board", "head": "President", "url": "about.html", "text": "President Adam Lloyd adam@omgsoftball.org"}, {"page": "About & Board", "head": "Vice President", "url": "about.html", "text": "Vice President Brooke Olsen brooke@omgsoftball.org"}, {"page": "About & Board", "head": "Secretary", "url": "about.html", "text": "Secretary Tammy Anderson tammy@omgsoftball.org"}, {"page": "About & Board", "head": "Treasurer &amp; 18U Coordinator", "url": "about.html", "text": "Treasurer & 18U Coordinator Shannon Capson shannon@omgsoftball.org"}, {"page": "About & Board", "head": "General Board", "url": "about.html", "text": "General Board Name Role Email Kathy Wilfert Clinics & Equipment kathy@omgsoftball.org Jason Woodhead 14U Coordinator jason@omgsoftball.org Tabitha Stratford 12U Coordinator tabitha@omgsoftball.org Audrey Wood Uniforms and All-Stars audrey@omgsoftball.org Brock Cordingley Website, Schedules, and 8U Coordinator brock@omgsoftball.org Tasha Mayfield 10U Coordinator tasha@omgsoftball.org Melissa Smith Social Media melissa@omgsoftball.org Board members (Directors) do not have fixed terms. When a seat opens, OMGS posts the opening, interviews applicants, and the Board fills it by vote. Executive officers are elected at the coaches meeting when a position is open. Join the board"}, {"page": "About & Board", "head": "We're looking for new board members for Spring.", "url": "about.html", "text": "We're looking for new board members for Spring. Help run the league your daughter plays in. Email us to apply. The Board interviews applicants and fills open seats by vote. Email contact@omgsoftball.org"}, {"page": "Divisions & Ages", "head": "Find my division", "url": "divisions.html", "text": "Find my division For the Fall 2026 / Spring 2027 seasons, based on the official age chart. Birth month Month January February March April May June July August September October November December Birth year Year 2024 2023 2022 2021 2020 2019 2018 2017 2016 2015 2014 2013 2012 2011 2010 2009 2008 2007 Find division Girls born September to December share an age group with girls born January to August of the next year. Final placement is up to OMGS."}, {"page": "Divisions & Ages", "head": "Fall 2026 / Spring 2027 age chart", "url": "divisions.html", "text": "Fall 2026 / Spring 2027 age chart Find your daughter's birth month and year to see her division. Born Sep to Dec or born Jan to Aug Age Division Sep to Dec 2019 Jan to Aug 2020 6 8U Sep to Dec 2018 Jan to Aug 2019 7 8U Sep to Dec 2017 Jan to Aug 2018 8 8U Sep to Dec 2016 Jan to Aug 2017 9 10U Sep to Dec 2015 Jan to Aug 2016 10 10U Sep to Dec 2014 Jan to Aug 2015 11 12U Sep to Dec 2013 Jan to Aug 2014 12 12U Sep to Dec 2012 Jan to Aug 2013 13 14U Sep to Dec 2011 Jan to Aug 2012 14 14U Sep to Dec 2010 Jan to Aug 2011 15 18U Sep to Dec 2009 Jan to Aug 2010 16 18U Sep to Dec 2008 Jan to Aug 2009 17 18U Sep to Dec 2007 Jan to Aug 2008 18 18U View the original age chart image"}, {"page": "Divisions & Ages", "head": "Division basics", "url": "divisions.html", "text": "Division basics From the OMGS league rules (OMGS Rules page and 2026 Coaches Handbook). Division Ball Pitching distance Bases Who pitches Run limit per half-inning No new inning after T-Ball/6U 11\" safety ball Coach pitch, then tee No diamond (plays on the T-Ball grass bowl) Coach pitches up to 5, then tee (3 swings). No score kept. Whole lineup bats 60 min or 3 innings 8U 11\" 35 ft 60 ft Coach pitch 5 runs 55 min 10U 11\" 35 ft 60 ft Player pitch 5 runs 55 min 12U 12\" 40 ft 60 ft Player pitch 7 runs 55 min 14U 12\" 43 ft 60 ft Player pitch 7 runs 65 min 18U 12\" 43 ft 60 ft Player pitch 7 runs 65 min Divisions play in the Spring and Fall seasons. Spring teams are drafted after a skill assessment. Fall teams are put together by OMGS, with no draft. Summer All-Stars are for 8U through 18U and have their own tryout and draft. T-Ball/6U: T-Ball/6U is for girls ages 3 to 5 (age prior to Sept 1 of the previous year). It is not shown on the age chart above."}, {"page": "Divisions & Ages", "head": "Playing up", "url": "divisions.html", "text": "Playing up Playing up is case by case and reviewed by the board. The player must be in her last year of an age group and have played All-Stars in that group, a parent must volunteer to coach, and she must be listed as a coach pick. See the rules for details."}, {"page": "Rules & Handbook", "head": "", "url": "rules.html", "text": "Contact details inside the 2026 PDFs (phone lines and older email addresses) are out of date. Please use contact@omgsoftball.org ."}, {"page": "Rules & Handbook", "head": "2026 Coaches Handbook (PDF)", "url": "rules.html", "text": "2026 Coaches Handbook (PDF) Full league and division rules, policies, clinics, All-Stars, and safety."}, {"page": "Rules & Handbook", "head": "2026 Coaches Selection (Draft) Rules (PDF)", "url": "rules.html", "text": "2026 Coaches Selection (Draft) Rules (PDF) How coach picks and the draft work."}, {"page": "Rules & Handbook", "head": "2027 D1 Prospects Rules (PDF)", "url": "rules.html", "text": "2027 D1 Prospects Rules (PDF) The governing rules for OMGS games, along with OMGS playing, division, and tournament rules."}, {"page": "Rules & Handbook", "head": "NFHS Softball Rules excerpt (PDF)", "url": "rules.html", "text": "NFHS Softball Rules excerpt (PDF) For reference only. D1 Prospects and OMGS rules govern OMGS games. Heads up: the 2026 handbook says the year-end tournament is double elimination. Tournaments are now single elimination. An updated handbook is coming soon."}, {"page": "Rules & Handbook", "head": "Key general rules", "url": "rules.html", "text": "Key general rules OMGS games follow D1 Prospects rules (our affiliated governing organization) plus OMGS playing, division, and tournament rules. See the 2027 D1 Prospects Rules (PDF) . Game time is forfeit time. Ten defensive players, open substitution, and teams bat everyone present. No player sits out two innings in a row. Eight girls are needed to start a game (except T-Ball/6U). Half innings end at three outs or a run limit: five runs (8U and 10U), seven runs (12U, 14U, 18U). Regular season games can end in a tie. Line-ups go into GameChanger at least 10 minutes before game time. No intentional walks. Leading off is allowed after the ball leaves the pitcher's hand. Metal cleats are allowed only in 14U and 18U. A player must play in at least 75% of her games to be eligible for All-Stars. T-Ball/6U players are not eligible. Both teams clean up their own dugout and bleacher area after every game."}, {"page": "Rules & Handbook", "head": "Sportsmanship", "url": "rules.html", "text": "Sportsmanship OMGS has a zero tolerance policy for abusive behavior. No derogatory or abusive remarks, including foul language, toward any coach, player, spectator, or umpire. This can lead to suspension, ejection from the park, or forfeit. Positive cheers are encouraged. Chants against the other team, especially the pitcher, are not okay."}, {"page": "Rules & Handbook", "head": "Year-end tournament", "url": "rules.html", "text": "Year-end tournament Single elimination, seeded by league win/loss record (tie breakers: head to head, runs allowed, run differential, runs scored). Games are 60 minutes for 8U, 10U, and 12U (no new inning after 55) and 70 minutes for 14U and 18U (no new inning after 65). Ties go to one International Tie Breaker inning, then put outs, then hits. The home team keeps the official score in GameChanger."}, {"page": "Important Dates", "head": "Three seasons a year", "url": "dates.html", "text": "Three seasons a year Spring"}, {"page": "Important Dates", "head": "Spring season", "url": "dates.html", "text": "Spring season Our main league season. Registration usually opens in mid-January. Players attend a skill assessment (tryout) before draft day, then teams are drafted. Coach picks do not need to attend. Summer"}, {"page": "Important Dates", "head": "All-Stars", "url": "dates.html", "text": "All-Stars June 1 to early August, for selected 8U to 18U players. All-Stars have their own tryout and draft, separate from spring. Fall"}, {"page": "Important Dates", "head": "Fall season", "url": "dates.html", "text": "Fall season Mid-August to October. There is no draft in the fall. OMGS puts the teams together."}, {"page": "Important Dates", "head": "Spring dates", "url": "dates.html", "text": "Spring dates Turn on JavaScript to see the list, or download the PDF below. Use + Add to calendar to save an event to your phone or computer calendar. All dates are subject to change. Download the 2026 Important Dates PDF"}, {"page": "Fields & Location", "head": "", "url": "fields.html", "text": "OMGS plays at three parks: Centennial Park (our home field), Tuscany East, and Western Springs."}, {"page": "Fields & Location", "head": "Centennial Park", "url": "fields.html", "text": "Centennial Park 13000 South 2700 West, Riverton, UT 84065 Directions (Google Maps) Directions (Apple Maps)"}, {"page": "Fields & Location", "head": "Diamonds", "url": "fields.html", "text": "Diamonds Field A, Field B and Field C."}, {"page": "Fields & Location", "head": "T-Ball Bowl", "url": "fields.html", "text": "T-Ball Bowl T-Ball has no diamond. It plays on the T-Ball grass bowl."}, {"page": "Fields & Location", "head": "Grass Bowl", "url": "fields.html", "text": "Grass Bowl Northeast, Northwest, Southwest, and Southeast corners. Same address."}, {"page": "Fields & Location", "head": "Snack Shack", "url": "fields.html", "text": "Snack Shack First aid kit and ice are available at the snack shack."}, {"page": "Fields & Location", "head": "Western Springs Park", "url": "fields.html", "text": "Western Springs Park 4570 W Goshute Drive, Riverton, UT 84096 Directions (Google Maps) Directions (Apple Maps)"}, {"page": "Fields & Location", "head": "Tuscany East (Tuscany Park)", "url": "fields.html", "text": "Tuscany East (Tuscany Park) 5469 W Toscana Way (12745 South), Herriman, UT 84096 Directions (Google Maps) Directions (Apple Maps)"}, {"page": "Fields & Location", "head": "Field Status", "url": "fields.html", "text": "Field Status If games are canceled for weather, they are rescheduled at the earliest possible time."}, {"page": "Fields & Location", "head": "Spring Preseason Practice Slots", "url": "fields.html", "text": "Spring Preseason Practice Slots Before spring games start, coaches reserve one-hour practice slots. Slots start Monday to Thursday at 4:30, 5:30 and 6:30 PM, Friday from 4:30 to 7:30 PM, and Saturday from 9 AM to 2 PM. Time Mon Tue Wed Thu Fri Sat 9:00 AM Open 10:00 AM Open 11:00 AM Open 12:00 PM Open 1:00 PM Open 4:30 PM Open Open Open Open Open 5:30 PM Open Open Open Open Open 6:30 PM Open Open Open Open Open"}, {"page": "Fields & Location", "head": "Practice locations", "url": "fields.html", "text": "Practice locations Centennial Park: Fields A, B and C Centennial Park: Large Grass Bowl (NW, SW, SE and NE) and the T-Ball Bowl Western Springs Park Tuscany East (Tuscany Park)"}, {"page": "Fields & Location", "head": "How to sign up", "url": "fields.html", "text": "How to sign up Coaches sign up through the league's Google Sheet, which the board shares with coaches before the season. Practice sign-up sheet No practice on Centennial Fields A, B and C after games start. All other fields are first come, first served after games start. Please be considerate of others. OMGS provides coaches with a permit for all fields. Have it with you any time you practice at Western Springs or Tuscany. Fall: there are no reserved slots. Fields are first come, first served at Tuscany, Western Springs and the Grass Bowl."}, {"page": "Volunteer & Coach", "head": "Coach with OMGS", "url": "volunteer.html", "text": "Coach with OMGS Our coaches are volunteers, and we could not do this without you. Head coaches, assistant coaches, and anyone helping on the field must complete an online coaching application before the first game. The head coach and one assistant must complete a background check release (through D1 Prospects). Head and assistant coaches must be at least 21, unless the Board grants an exception. Every team needs at least one approved adult female (coach, team parent, or chaperone) at every practice, game, and team activity. All coaches complete an online Child Safety Training class before coaching. Coaches and assistants attend the mandatory coaches meeting and clinic in March and help at the pitching and players clinics. A coach's daughter must be listed as a coach pick for the coach to be selected. Coach applications for Spring 2027 are coming soon. Questions? Email contact@omgsoftball.org . Read the 2026 Coaches Handbook · Draft rules"}, {"page": "Volunteer & Coach", "head": "Snack Shack", "url": "volunteer.html", "text": "Snack Shack Each team provides one volunteer (14 or older) to work the BBQ at its scheduled times, listed on your team schedule. These times will not conflict with your games. If a team does not provide a volunteer, the team forfeits one game."}, {"page": "Volunteer & Coach", "head": "Other ways to help", "url": "volunteer.html", "text": "Other ways to help Team parent Scorekeeper (GameChanger). The parent meeting is highly recommended for scorekeeping training. Centennial Park clean-up day Board service. When a seat opens, OMGS posts it and interviews applicants. Questions? Email contact@omgsoftball.org ."}, {"page": "FAQ", "head": "", "url": "faq.html", "text": "Expand all How do I register? Click any Register button on this site. Spring registration usually opens in mid-January. 2027 fees will be posted when registration opens. Is there a late fee? No. OMGS does not charge late fees. The 2027 registration deadline will be posted when registration opens. Where are games played? At Centennial Park in Riverton (our home field), Tuscany East, and Western Springs. Addresses and map links are on the Fields page. What division will my daughter play in? Check the age chart . It is based on birth month and year. When are the seasons? OMGS has three seasons: Spring, All-Stars in the summer (June 1 to early August), and Fall (mid-August to October). See Important Dates . How long is a season? Every team is guaranteed 10 games each season. There is also a single elimination year-end tournament as an extra. Is there a draft? In the spring, yes. Players attend a skill assessment (tryout) before draft day (coach picks do not need to), then teams are drafted. All-Stars have their own tryout and draft. In the fall there is no draft, and OMGS puts the teams together. See the draft rules . Can my daughter play up? Case by case with board review. See Divisions for the requirements. Do parents need to volunteer? Each team provides a Snack Shack volunteer (14 or older) at its scheduled times. Missing a shift costs the team a game. What about All-Stars? Players must play in at least 75% of their games. T-Ball/6U is not eligible. Details are in the handbook . Is financial help available? Yes. No eligible player is turned away only because she cannot pay. Email contact@omgsoftball.org and the Executive Board will keep it confidential. Can I get a refund? Our refund policy will be posted soon. In the meantime, email contact@omgsoftball.org . Is there insurance? OMGS carries secondary medical insurance, which pays after the family's own insurance. See the handbook for details."}, {"page": "Contact", "head": "Email", "url": "contact.html", "text": "Email contact@omgsoftball.org"}, {"page": "Contact", "head": "Mail", "url": "contact.html", "text": "Mail P.O. Box 385 Riverton, UT 84065-0385 Looking for a specific board member? See About & Board ."}, {"page": "Contact", "head": "Ready to sign up?", "url": "contact.html", "text": "Ready to sign up? Register"}, {"page": "Sponsors", "head": "", "url": "sponsors.html", "text": "Thank you to the businesses and partners who support OMGS."}, {"page": "Sponsors", "head": "Become a sponsor", "url": "sponsors.html", "text": "Become a sponsor Help keep softball affordable for local girls. Sponsorship levels are coming soon. Reach out and we will get you the details. Email us about sponsoring"}, {"page": "Sponsors", "head": "Partners &amp; Sister Leagues", "url": "sponsors.html", "text": "Partners & Sister Leagues"}, {"page": "Sponsors", "head": "Partner", "url": "sponsors.html", "text": "Partner D1 Prospects &#8599; (opens in a new tab)"}, {"page": "Sponsors", "head": "Sister leagues", "url": "sponsors.html", "text": "Sister leagues West Valley Fastpitch &#8599; (opens in a new tab) Mt Olympus Fast Pitch &#8599; (opens in a new tab) Vernal Girls Softball &#8599; (opens in a new tab) Taylorsville Fast-pitch Softball League &#8599; (opens in a new tab)"}, {"page": "All-Stars", "head": "", "url": "allstars.html", "text": "2027 All-Star dates: Coming soon . In 2026, coach requests were due in mid-April, nominations in late April, tryouts were in early May, and the All-Star season ran in the summer. The summer All-Star season runs June 1 to early August."}, {"page": "All-Stars", "head": "What is All-Stars?", "url": "allstars.html", "text": "What is All-Stars? After the spring season, OMGS forms All-Star teams in each division from 8U through 18U. All-Star teams practice together and play a summer tournament season (June 1 to early August), including the OMGS All-Star Invitational in Riverton and the D1 Prospects Rec/All-Star State Tournament. There is no All-Star team for T-Ball/6U."}, {"page": "All-Stars", "head": "Who is eligible?", "url": "allstars.html", "text": "Who is eligible? She must play in at least 75% of her league games. Her coach must nominate her (head coaches nominate all eligible, interested players after talking with families about the time commitment). She must attend tryouts, unless cleared by the board ahead of time. She must be able to make practices and the required tournaments. She tries out only in the age group she played in during the season. Girls who played up try out in the group they were placed in. 2027 D1 Prospects All-Star Rules: All-Star players must come from the same rec league, and a player on an All-Star roster may not be on any accelerated (competitive) roster from April 1 until the State Tournament ends. All-Star teams and players may play in no more than 2 accelerated events in that window. Any exceptions must be cleared by the OMGS board before tryouts."}, {"page": "All-Stars", "head": "How coaches are selected", "url": "allstars.html", "text": "How coaches are selected Interested coaches submit an All-Star coach request to the board. The board evaluates applicants on how they coach, not just what they know: developing every player, building confidence, treating players fairly, sportsmanship and composure, clear communication, a positive team culture, and leading the whole coaching staff. Board members with a conflict (they, a spouse, or a daughter are involved in that age group's All-Stars) do not take part in that age group's evaluations. Selected coaches must have a coach application on file and a current background check. Read the OMGS All-Star Coach Standards (PDF)"}, {"page": "All-Stars", "head": "How teams are formed", "url": "allstars.html", "text": "How teams are formed Tryouts are held at Centennial Park and supervised by the board. All-Star coaches may keep (freeze) up to 6 players from their own spring team. In 10U and up, pitchers and catchers are drafted first, with a maximum of 3 pitchers and 2 catchers per team, so teams have balanced pitching and catching. The rest of each roster is filled through a draft in a set order for each division. The board resolves any disputes. All-Star uniforms use the official league colors: black, lavender, silver, and teal, with the OMGS logo."}, {"page": "All-Stars", "head": "Tournaments", "url": "allstars.html", "text": "Tournaments All-Star teams play a set of summer tournaments. In 2026, players committed to four tournaments. The OMGS All-Star Invitational and the D1 State Tournament were required, plus one chosen by the coach. D1 Prospects also requires each team to play at least 2 D1 All-Star qualifying events to be eligible for State. 2026 tournament (for reference) Dates Sandlot Showdown June 12 to 13 Clash of the Titans June 19 to 20 Gerald Wright Classic June 25 to 27 OMGS All-Star Invitational (CR Hamilton Sports Complex, Riverton) July 16 to 18 Unplugged All Nighter July 24 to 25 Untamed July 24 to 25 A League of Their Own July 31 to August 1 D1 Prospects Rec/All-Star State August 7 to 8 2027 tournaments: Coming soon"}, {"page": "All-Stars", "head": "Cost", "url": "allstars.html", "text": "Cost All-Star fee: $360"}, {"page": "All-Stars", "head": "Expectations", "url": "allstars.html", "text": "Expectations All-Stars is a real commitment. Spring teams come first until the season ends, and players chosen for All-Stars are expected to make a reasonable effort to attend practices and every required tournament game."}, {"page": "All-Stars", "head": "2027 D1 Prospects All-Star Rules (PDF)", "url": "allstars.html", "text": "2027 D1 Prospects All-Star Rules (PDF) Tournament and eligibility rules from D1 Prospects for the 2027 season."}, {"page": "All-Stars", "head": "OMGS All-Star Coach Standards (PDF)", "url": "allstars.html", "text": "OMGS All-Star Coach Standards (PDF) What great All-Star coaching looks like."}, {"page": "All-Stars", "head": "2026 Coaches Handbook (PDF)", "url": "allstars.html", "text": "2026 Coaches Handbook (PDF) Includes the 2026 All-Star policy."}, {"page": "Coaches & Parents", "head": "", "url": "coaches.html", "text": "Everything coaches and parents need for the season, in one place. The 2026 slides are posted for reference. 2027 versions are coming soon . Contact details inside the 2026 PDFs (phone lines and older email addresses) are out of date. Please use contact@omgsoftball.org ."}, {"page": "Coaches & Parents", "head": "2026 Coaches Handbook", "url": "coaches.html", "text": "2026 Coaches Handbook Rules, policies, clinics, All-Stars, safety, and forms."}, {"page": "Coaches & Parents", "head": "2026 Coaches Meeting slides", "url": "coaches.html", "text": "2026 Coaches Meeting slides From the March coaches meeting and Annual Meeting."}, {"page": "Coaches & Parents", "head": "2026 Parent Meeting slides", "url": "coaches.html", "text": "2026 Parent Meeting slides For team parents, first-time OMGS parents, and scorekeepers."}, {"page": "Coaches & Parents", "head": "2026 Draft (Coaches Selection) Rules", "url": "coaches.html", "text": "2026 Draft (Coaches Selection) Rules How coach picks and the spring draft work."}, {"page": "Coaches & Parents", "head": "NFHS Softball Rules excerpt", "url": "coaches.html", "text": "NFHS Softball Rules excerpt For reference only. D1 Prospects and OMGS rules govern OMGS games."}, {"page": "Coaches & Parents", "head": "2027 D1 Prospects All-Star Rules", "url": "coaches.html", "text": "2027 D1 Prospects All-Star Rules Tournament and eligibility rules for All-Stars."}, {"page": "Coaches & Parents", "head": "All-Star Coach Standards", "url": "coaches.html", "text": "All-Star Coach Standards The OMGS standard for All-Star coaches. Heads up: year-end tournaments are single elimination in both spring and fall. Any older document that says double elimination is out of date."}, {"page": "Coaches & Parents", "head": "For coaches", "url": "coaches.html", "text": "For coaches Before you coach: complete the online coach application, the background check release, and the online Child Safety Training. Practices: See Spring preseason practice slots . OMGS expects two practices a week before games start and at least one a week after that (unless you have three games that week). Reserve preseason slots through the league sign-up sheet. After games start, fields other than Centennial A, B and C are first come, first served. No practices at private homes or church fields. In Riverton, practice fields must be a softball field or have a backstop. Equipment bag: each team gets 4 batting helmets with face masks, 2 bats, a catcher's helmet with mask plus shin guards and chest protector (except T-Ball), 6 softballs and 4 wiffle balls (6 softballs only for T-Ball), and a batting tee for T-Ball. Sign it out at the start of the season and return everything at the end. GameChanger: download the app, tap +, and import from Sports Connect so schedules and rosters are correct. Line-ups go in at least 10 minutes before game time. Snack Shack / BBQ: each team covers its scheduled 2-hour BBQ shifts. Shift times are emailed to the head coach and team parent. Rainouts: game cancellations are emailed to the league. Make-up games are posted on the website. Awards: awards and medals are set by the Board each season and announced before the season ends."}, {"page": "Coaches & Parents", "head": "Play Like A GIRL program", "url": "coaches.html", "text": "Play Like A GIRL program Grit, Integrity, Respect, and Love for the Game. Each week OMGS recognizes one player per division, one team league-wide, and one coach league-wide for effort, character, sportsmanship, and positive impact, not just wins. Recipients are entered in a raffle for prizes like tickets, league swag, and custom gear."}, {"page": "Coaches & Parents", "head": "For parents", "url": "coaches.html", "text": "For parents Parent meeting: held in March. Mandatory for team parents, first-time OMGS parents, and scorekeepers (scorekeeping training). No children. Team photos: registration includes one free team photo per player. Photos are taken at Centennial Park, and your coach will share your time. Team treats: treat bags are not part of registration. Families take turns bringing post-game treats or buy them at the Snack Shack. Sportsmanship: positive cheers only. OMGS has zero tolerance for abusive behavior toward anyone at the park. Insurance: OMGS carries secondary medical insurance, which pays after your family's insurance. All-Stars: see the All-Stars page for eligibility and how it works. Questions? Email contact@omgsoftball.org ."}];
